(() => {
 // Final tokens append once; provisional tokens are replaced on each response.
 function accumulator(emit,preview,expectTranslation=true){let original='',translated='',turn=1,originalEnded=false,translationEnded=false;
  function flush(force=false){if(!original.trim())return;if(!force&&(!originalEnded||(expectTranslation&&!translationEnded)))return;emit(original.trim(),{turn:turn++,translation:translated.trim()});original=translated='';originalEnded=translationEnded=false;}
  function push(data){let interimOriginal='',interimTranslation='';for(const t of data.tokens||[]){const isTranslation=t.translation_status==='translation';if(t.text==='<end>'||t.text==='<fin>'){if(t.is_final){if(isTranslation)translationEnded=true;else originalEnded=true;}continue;}if(typeof t.text!=='string'||/^<[^>]+>$/.test(t.text))continue;if(t.is_final){if(isTranslation)translated+=t.text;else original+=t.text;}else if(isTranslation)interimTranslation+=t.text;else interimOriginal+=t.text;}
   const text=(original+interimOriginal).trim(),translation=(translated+interimTranslation).trim();if(text)preview({text,translation,turn});
   // End markers may be untagged and follow translation in the same response.
   if(originalEnded&&translated&&!interimTranslation)translationEnded=true;
   flush(!!data.finished);if((original.length+translated.length)>12000)throw Error('Trecho de fala muito longo. Desligue o microfone para salvar.');
  }
  return {push,flush:()=>flush(true)};
 }
 let active,generation=0;
 async function start(stream,c){if(active)throw Error('Reconhecimento já ativo.');const ticket=++generation,credential=await c.session();if(ticket!==generation)throw Error('Reconhecimento cancelado.');const ws=new WebSocket(credential.url,['soniox-api-key',credential.apiKey]);let context,source,capture,mute,stopping=false,closed=false,stopPromise,resolveFinished,rejectFinished,tail=[],tailSize=0;const finish=new Promise((resolve,reject)=>{resolveFinished=resolve;rejectFinished=reject});finish.catch(()=>{});let writes=Promise.resolve();
  const collect=accumulator((text,meta)=>{writes=writes.then(()=>c.text(text,{...meta,target:credential.target}));writes.catch(()=>{});},data=>c.preview({...data,target:credential.target}),!!credential.config.translation);
  function release(){if(closed)return;closed=true;if(capture)capture.port.onmessage=null;source?.disconnect();capture?.disconnect();mute?.disconnect();context?.close().catch(()=>{});ws.close();tail=[];tailSize=0;}
  function failed(error){if(closed)return;c.status(error.message+' O áudio da chamada continua ligado.');c.reconnect?.(true);collect.flush();Promise.resolve(c.gap(error.message)).catch(()=>{});rejectFinished(error);release();}
  const socketReady=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{reject(Error('A Soniox não respondeu.'));release();},12000);ws.onopen=()=>{clearTimeout(timer);ws.send(JSON.stringify(credential.config));resolve()};ws.onerror=()=>{clearTimeout(timer);const e=Error('Conexão com a Soniox interrompida.');reject(e);failed(e)};});
  ws.onmessage=e=>{try{const data=JSON.parse(e.data);if(data.error_code){const billing=['organization_balance_exhausted','project_monthly_budget_exhausted','organization_monthly_budget_exhausted'].includes(data.error_type);failed(Error(billing?'Soniox sem saldo ou com limite atingido. Adicione créditos no painel.':'Soniox indisponível ('+(data.error_type||'erro')+'). Reconecte as legendas.'));return;}collect.push(data);if(data.finished){resolveFinished();if(!stopping){c.status('As legendas foram finalizadas. Reconecte para continuar.');c.reconnect?.(true);}release();}}catch(error){failed(error)}};
  ws.onclose=()=>{if(!closed)failed(Error('A conexão das legendas foi encerrada antes da confirmação.'));};
 const pcm=part=>{const samples=window.asrUtils.resample(part,context.sampleRate),b=new ArrayBuffer(samples.length*2),v=new DataView(b);for(let i=0;i<samples.length;i++)v.setInt16(i*2,Math.round(Math.max(-1,Math.min(1,samples[i]))*32767),true);return b;};
  function sendTail(){if(!tailSize)return;if(ws.readyState!==1||ws.bufferedAmount>512000)throw Error('Conexão de voz sobrecarregada. Reconecte as legendas.');const samples=new Float32Array(tailSize);let at=0;for(const p of tail){samples.set(p,at);at+=p.length;}ws.send(pcm(samples));tail=[];tailSize=0;}
  active={abort(){rejectFinished(Error('Reconhecimento cancelado.'));release();active=null;},stop(){if(stopPromise)return stopPromise;stopPromise=(async()=>{stopping=true;if(capture)capture.port.onmessage=null;try{if(!closed){sendTail();ws.send('');let timer;try{await Promise.race([finish,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('A Soniox não confirmou a última fala.')),15000)})]);}finally{clearTimeout(timer)}}await writes;}catch(error){collect.flush();await writes;throw error;}finally{release();active=null}})();return stopPromise;}};
  try{await socketReady;if(closed)throw Error('Legendas indisponíveis.');context=new AudioContext();await context.audioWorklet.addModule('/capture-processor.js');await context.resume();if(closed){await context.close();throw Error('Reconhecimento cancelado.');}source=context.createMediaStreamSource(stream);capture=new AudioWorkletNode(context,'classroom-capture',{channelCount:1,channelCountMode:'explicit'});mute=context.createGain();mute.gain.value=0;capture.port.onmessage=e=>{if(stopping||closed)return;try{tail.push(e.data);tailSize+=e.data.length;if(tailSize>=context.sampleRate*.08)sendTail();}catch(error){failed(error)}};source.connect(capture);capture.connect(mute);mute.connect(context.destination);c.reconnect?.(false);c.status('Microfone ligado. Transcrição e tradução em tempo real pela Soniox.');}catch(error){release();active=null;throw error;}
 }
 window.sonioxASR={start,stop:()=>{generation++;return active?.stop()||Promise.resolve()},abort:()=>{generation++;return active?.abort()},accumulator};
})();
